  leftBubblesY = 0.88,
  leftBubblesScale = 0.8,

  // Right Bubbles defaults
  rightBubblesColor = "#bc13fe",
  rightBubblesX = 0.78,
  rightBubblesY = 0.72,
  rightBubblesScale = 0.9,

  // Center Bubbles defaults
  centerBubblesColor = "#ffdd00",
  centerBubblesX = 0.45,
  centerBubblesY = 0.82,
  centerBubblesScale = 0.8,

  // Spark 1 defaults
  spark1Color = "#ffdd00",
